# The PatchPilot web page, embedded so no static folder is needed (works on Vercel).
HTML = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>PatchPilot</title>\n<style>\n:root{--ink:#080d1b;--glass:#111a30b8;--line:#2a3860;--tx:#eaeefb;--mu:#8793b5;--amber:#ffb454;--pass:#7fe08a;--fail:#ff6b6b;--blue:#6f8cff}\n*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-snap-type:y proximity}\nbody{margin:0;background:var(--ink);color:var(--tx);font:16px/1.55 "Avenir Next","Segoe UI",system-ui,sans-serif;overflow-x:hidden}\n#gl{position:fixed;inset:0;width:100%;height:100%;z-index:0}\n.nav{position:fixed;top:0;left:0;right:0;z-index:5;display:flex;justify-content:space-between;align-items:center;padding:16px 28px;backdrop-filter:blur(8px)}\n.nav b{font-size:18px;letter-spacing:-.02em}.badge{font-size:13px;color:var(--mu);border:1px solid var(--line);border-radius:99px;padding:4px 12px}\n.panel{position:relative;z-index:1;min-height:100vh;display:flex;flex-direction:column;justify-content:center;padding:90px 7vw 50px;scroll-snap-align:start}\n.hero{align-items:flex-start;pointer-events:none}.hero *{pointer-events:auto}\nh1{font-size:clamp(44px,8vw,104px);line-height:.95;letter-spacing:-.045em;margin:0 0 18px;max-width:11ch}\n.sub{color:var(--mu);font-size:19px;max-width:34ch;margin:0 0 30px}\n.row{display:flex;gap:12px;flex-wrap:wrap}\nbutton{position:relative;overflow:hidden;border:0;border-radius:10px;padding:13px 24px;font:600 16px inherit;cursor:pointer;background:var(--amber);color:#1b1200;transition:transform .2s,box-shadow .2s}\nbutton.ghost{background:transparent;color:var(--tx);border:1px solid var(--line)}\nbutton:hover{transform:translateY(-3px);box-shadow:0 10px 30px #ffb45440}button:active{transform:scale(.96)}button:disabled{opacity:.5;cursor:wait}\n:focus-visible{outline:2px solid var(--amber);outline-offset:3px}\n.ripple{position:absolute;border-radius:50%;background:#fff6;transform:scale(0);animation:rp .6s ease-out forwards;pointer-events:none}\n@keyframes rp{to{transform:scale(3.2);opacity:0}}\n.hint{margin-top:44px;color:var(--mu);font-size:13px;animation:bob 2s ease-in-out infinite}@keyframes bob{50%{transform:translateY(8px)}}\n.glass{background:var(--glass);border:1px solid var(--line);border-radius:16px;padding:24px;backdrop-filter:blur(14px);max-width:760px}\nh2{font-size:clamp(28px,4vw,44px);letter-spacing:-.03em;margin:0 0 18px}\nlabel{color:var(--mu);font-size:13px}\ninput,textarea{width:100%;background:#0a1226;color:var(--tx);border:1px solid var(--line);border-radius:10px;padding:12px;font:inherit;margin:4px 0 14px;transition:border-color .2s,box-shadow .2s}\ninput:focus,textarea:focus{border-color:var(--amber);box-shadow:0 0 0 4px #ffb45422;outline:0}\ntextarea{min-height:92px;font:14px ui-monospace,Menlo,monospace}\n.chips{display:flex;align-items:center;gap:10px;margin-bottom:6px;flex-wrap:wrap}\n.chip{display:flex;align-items:center;gap:10px;padding:10px 16px;border:1px solid var(--line);border-radius:12px;background:var(--glass);transition:.4s}\n.chip i{width:12px;height:12px;border-radius:50%;background:#4a5a85;transition:.4s}.chip small{display:block;color:var(--mu);font-size:11px;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.chip.running{border-color:var(--amber)}.chip.running i{background:var(--amber);animation:pl 1s infinite}\n.chip.done i{background:var(--pass);box-shadow:0 0 14px var(--pass)}.chip.failed i{background:var(--fail)}\n@keyframes pl{0%{box-shadow:0 0 0 0 #ffb454aa}100%{box-shadow:0 0 0 14px #ffb45400}}\n.meter{color:var(--mu);font-size:14px;margin:6px 0 16px}.meter b{color:var(--tx);font-variant-numeric:tabular-nums}\n.rail{display:flex;gap:18px;overflow-x:auto;scroll-snap-type:x mandatory;padding:10px 7vw 24px;margin:0 -7vw;cursor:grab;scrollbar-width:none;min-height:200px}\n.rail::-webkit-scrollbar{display:none}.rail.drag{scroll-snap-type:none;cursor:grabbing}\n.card{flex:0 0 min(560px,86vw);scroll-snap-align:center;transition:transform .15s;animation:in .5s cubic-bezier(.2,.8,.2,1);max-width:none}\n@keyframes in{from{opacity:0;transform:translateX(60px) scale(.94)}}\n.card h3{margin:0 0 8px;font-size:17px}.tag{color:var(--mu);font-weight:400;font-size:12px}\npre{margin:8px 0 0;background:#070c19;border-radius:10px;padding:12px;overflow:auto;font:12.5px/1.5 ui-monospace,Menlo,monospace;max-height:300px;white-space:pre-wrap}\n.add{color:var(--pass)}.del{color:var(--fail)}\n.banner{font-size:22px;font-weight:700;padding:14px 20px;border-radius:12px;margin-top:6px;animation:in .5s;max-width:760px}\n.banner.ok{background:#7fe08a1f;color:var(--pass)}.banner.bad{background:#ff6b6b1f;color:var(--fail)}\n.empty{color:var(--mu)}\n#toast{position:fixed;left:50%;bottom:30px;transform:translate(-50%,20px);opacity:0;z-index:9;background:var(--glass);border:1px solid var(--amber);border-radius:12px;padding:10px 18px;backdrop-filter:blur(10px);transition:.3s;pointer-events:none}\n#toast.on{opacity:1;transform:translate(-50%,0)}\n.rv{opacity:0;transform:translateY(46px);transition:opacity .8s,transform .8s cubic-bezier(.2,.8,.2,1)}.rv.in{opacity:1;transform:none}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}html{scroll-behavior:auto}}\n</style></head><body>\n<canvas id="gl"></canvas><div id="toast"></div>\n<div class="nav"><b>PatchPilot</b><span class="badge" id="mode">Live mode</span></div>\n\n<section class="panel hero" id="top">\n <h1>Bugs in. Verified fixes out.</h1>\n <p class="sub">Three Nemotron agents plan, patch and test your code, live on Nebius Token Factory.</p>\n <div class="row"><button id="demo">Play demo</button><button class="ghost" id="own">Try your own bug</button></div>\n <div class="hint">Scroll, or click an agent in the 3D scene</div>\n</section>\n\n<section class="panel" id="lab">\n <div class="glass rv">\n  <h2>What\'s broken?</h2>\n  <label for="repo">Repo (example:py_bug or an https git URL)</label><input id="repo" value="example:py_bug">\n  <label for="bug">Bug description or failing test output</label>\n  <textarea id="bug">average([2, 4, 6]) returns 6.0 instead of 4.0, and test_calc.py fails.</textarea>\n  <button id="go">Fix it</button>\n </div>\n</section>\n\n<section class="panel" id="out">\n <h2 class="rv">Watch the agents work</h2>\n <div class="chips rv">\n  <div class="chip" id="c0"><i></i><div>Planner<small>Nemotron Ultra</small></div></div>\n  <div class="chip" id="c1"><i></i><div>Coder<small>Nemotron Super</small></div></div>\n  <div class="chip" id="c2"><i></i><div>Tester<small>Nemotron Nano</small></div></div>\n </div>\n <div class="meter">Tokens used <b id="tok">0</b></div>\n <div class="rail" id="rail"><div class="glass card empty">Results show up here. Swipe or drag to move through them.</div></div>\n <div id="end"></div>\n</section>\n\n<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n<script>\nconst $=id=>document.getElementById(id),RM=matchMedia("(prefers-reduced-motion:reduce)").matches;\nconst esc=s=>(s||"").replace(/[&<>]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[c]));\nconst cols={idle:0x4a5a85,running:0xffb454,done:0x7fe08a,failed:0xff6b6b};\nconst ROLES=["Planner (Nemotron Ultra): finds the root cause","Coder (Nemotron Super): writes the patch","Tester (Nemotron Nano): writes and runs tests"];\nlet st=["idle","idle","idle"],mx=0,my=0,bursts=[],T=window.THREE;\nfunction toast(t){const e=$("toast");e.textContent=t;e.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("on"),2200)}\n\n/* ---------- 3D scene ---------- */\nlet sats=[],core,scene,cam,ren,ray,pulse=[0,0,0];\nif(T){\n ren=new T.WebGLRenderer({canvas:$("gl"),antialias:true,alpha:true});ren.setPixelRatio(Math.min(devicePixelRatio,2));\n scene=new T.Scene();cam=new T.PerspectiveCamera(55,1,.1,100);cam.position.z=9;ray=new T.Raycaster();\n core=new T.Group();\n core.add(new T.Mesh(new T.IcosahedronGeometry(1.7,1),new T.MeshBasicMaterial({color:0x6f8cff,wireframe:true,transparent:true,opacity:.5})));\n core.add(new T.Mesh(new T.IcosahedronGeometry(.95,0),new T.MeshBasicMaterial({color:0xffb454})));\n scene.add(core);\n for(let i=0;i<3;i++){\n  const g=new T.Group();g.rotation.set(Math.PI/2+i*.4,i*.55,0);\n  g.add(new T.Mesh(new T.TorusGeometry(3.2+i*.9,.012,8,140),new T.MeshBasicMaterial({color:0x2a3860})));\n  const s=new T.Mesh(new T.OctahedronGeometry(.36+i*.04),new T.MeshBasicMaterial({color:cols.idle}));s.userData.i=i;g.add(s);\n  g.userData={s,r:3.2+i*.9,ph:i*2.1};scene.add(g);sats.push(g)}\n const n=700,p=new Float32Array(n*3);for(let i=0;i<n*3;i++)p[i]=(Math.random()-.5)*50;\n const sg=new T.BufferGeometry();sg.setAttribute("position",new T.BufferAttribute(p,3));\n scene.add(new T.Points(sg,new T.PointsMaterial({color:0x8793b5,size:.05})));\n const rs=()=>{ren.setSize(innerWidth,innerHeight);cam.aspect=innerWidth/innerHeight;cam.updateProjectionMatrix();core.position.x=innerWidth>800?3:0};rs();addEventListener("resize",rs);\n let a=0;(function loop(){requestAnimationFrame(loop);\n  const run=st.includes("running"),k=RM?0:1;a+=(run?.03:.006)*k;\n  const max=Math.max(1,document.documentElement.scrollHeight-innerHeight),p=scrollY/max;\n  cam.position.z=9-p*2.5;cam.position.x+=(mx*1.2-cam.position.x)*.05;cam.position.y+=(-my*.8-p*1.5-cam.position.y)*.05;cam.lookAt(core.position.x*.5,0,0);\n  scene.rotation.y=p*1.6;core.rotation.y+=(run?.03:.006)*k;core.rotation.x+=.004*k;\n  sats.forEach((g,i)=>{const s=g.userData.s,t=a*(1+i*.3)+g.userData.ph;s.position.set(Math.cos(t)*g.userData.r,Math.sin(t)*g.userData.r,0);s.rotation.x+=.03*k;s.rotation.y+=.04*k;\n   pulse[i]*=.92;s.scale.setScalar(1+pulse[i]+(st[i]==="running"?.25+Math.sin(a*8)*.15:0))});\n  bursts=bursts.filter(b=>{b.life--;const q=b.o.geometry.attributes.position;for(let j=0;j<q.count;j++){q.array[j*3]+=b.v[j*3];q.array[j*3+1]+=b.v[j*3+1];q.array[j*3+2]+=b.v[j*3+2]}q.needsUpdate=true;b.o.material.opacity=b.life/90;if(b.life<=0){scene.remove(b.o);return false}return true});\n  ren.render(scene,cam)})();\n}\nfunction boom(c){if(!T)return;const n=220,p=new Float32Array(n*3),v=new Float32Array(n*3);\n for(let i=0;i<n*3;i++)v[i]=(Math.random()-.5)*.28;const g=new T.BufferGeometry();g.setAttribute("position",new T.BufferAttribute(p,3));\n const o=new T.Points(g,new T.PointsMaterial({color:c,size:.09,transparent:true}));o.position.copy(core.position);scene.add(o);bursts.push({o,v,life:90})}\nfunction setState(i,s){st[i]=s;$("c"+i).className="chip "+(s==="idle"?"":s);if(T)sats[i].userData.s.material.color.setHex(cols[s])}\naddEventListener("pointermove",e=>{mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5});\naddEventListener("click",e=>{if(!T||e.target.closest("button,input,textarea,.rail,.glass"))return;\n ray.setFromCamera({x:e.clientX/innerWidth*2-1,y:-(e.clientY/innerHeight)*2+1},cam);\n const h=ray.intersectObjects(sats.map(g=>g.userData.s))[0];if(h){const i=h.object.userData.i;pulse[i]=1;toast(ROLES[i])}});\n\n/* ---------- click ripple, scroll reveal, swipe, tilt ---------- */\ndocument.addEventListener("pointerdown",e=>{const b=e.target.closest("button");if(!b)return;const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height),s=document.createElement("span");\n s.className="ripple";s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;b.appendChild(s);setTimeout(()=>s.remove(),650)});\nconst io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add("in")),{threshold:.2});document.querySelectorAll(".rv").forEach(e=>io.observe(e));\nconst rail=$("rail");let dn=false,sx=0,sl=0;\nrail.addEventListener("pointerdown",e=>{if(e.pointerType==="mouse"&&!e.target.closest("pre")){dn=true;sx=e.clientX;sl=rail.scrollLeft;rail.classList.add("drag")}});\naddEventListener("pointermove",e=>{if(dn)rail.scrollLeft=sl-(e.clientX-sx)});addEventListener("pointerup",()=>{dn=false;rail.classList.remove("drag")});\nrail.addEventListener("pointermove",e=>{const c=e.target.closest(".card");if(!c||dn)return;const r=c.getBoundingClientRect();\n c.style.transform=`perspective(800px) rotateY(${((e.clientX-r.left)/r.width-.5)*8}deg) rotateX(${-((e.clientY-r.top)/r.height-.5)*8}deg)`});\nrail.addEventListener("pointerout",e=>{const c=e.target.closest(".card");if(c)c.style.transform=""});\n\n/* ---------- agent events (shared by live + demo) ---------- */\nconst idx={planner:0,coder:1,tester:2};\nfunction card(h,body){if(rail.querySelector(".empty"))rail.innerHTML="";const d=document.createElement("div");d.className="glass card";d.innerHTML=`<h3>${h}</h3>${body}`;rail.appendChild(d);setTimeout(()=>rail.scrollTo({left:rail.scrollWidth,behavior:"smooth"}),60)}\nfunction cdiff(d){return d.split("\\n").map(l=>l[0]==="+"&&l[1]!=="+"?`<span class="add">${esc(l)}</span>`:l[0]==="-"&&l[1]!=="-"?`<span class="del">${esc(l)}</span>`:esc(l)).join("\\n")}\nfunction handle(m){if(m.total)$("tok").textContent=m.total.toLocaleString();\n if(m.step==="load")card("Repo loaded",`<span class="tag">${esc(m.detail)}</span>`);\n else if(m.step in idx){const i=idx[m.step];setState(i,m.status);if(m.model)$("c"+i).querySelector("small").textContent=m.model.split("/").pop();\n  if(m.step==="planner"&&m.status==="done")card("Root cause",`<p>${esc(m.detail)}</p><ol>${(m.steps||[]).map(s=>`<li>${esc(s)}</li>`).join("")}</ol>`);\n  if(m.step==="coder"&&m.status==="done")card(`Patch, attempt ${m.attempt}`,`<pre>${cdiff(m.diff)}</pre>`);\n  if(m.step==="tester"&&m.status!=="running"){card(`Tests ${m.status==="done"?"passed":"failed"}, attempt ${m.attempt}`,`<pre>${esc(m.output)}</pre>`);if(m.status==="failed"){setState(1,"idle");pulse[2]=1}}}\n else if(m.step==="final"){const ok=m.status==="done";$("go").disabled=$("demo").disabled=false;\n  $("end").innerHTML=`<div class="banner ${ok?"ok":"bad"}">${ok?"Fixed and verified":"Could not fix within the retry limit"}</div>`;\n  if(ok){boom(0x7fe08a);boom(0xffb454);card("PR description",`<pre>${esc(m.summary)}</pre>`);if(T)core.children[1].material.color.setHex(0x7fe08a)}}\n else if(m.step==="error"){$("go").disabled=$("demo").disabled=false;card("Something went wrong",`<pre>${esc(m.detail)}</pre>`)}}\nfunction reset(){rail.innerHTML="";$("end").innerHTML="";$("tok").textContent=0;[0,1,2].forEach(i=>setState(i,"idle"));if(T)core.children[1].material.color.setHex(0xffb454)}\n\nfunction live(){reset();$("mode").textContent="Live mode";$("go").disabled=$("demo").disabled=true;$("out").scrollIntoView();\n const es=new EventSource("/api/run?repo="+encodeURIComponent($("repo").value)+"&bug="+encodeURIComponent($("bug").value));\n es.onmessage=e=>{const m=JSON.parse(e.data);handle(m);if(m.step==="final"||m.step==="error")es.close()};\n es.onerror=()=>{es.close();$("go").disabled=$("demo").disabled=false}}\n\n/* ---------- scripted demo (no API calls, always works on camera) ---------- */\nconst D1="--- a/calc.py\\n+++ b/calc.py\\n def average(nums):\\n-    if not nums:\\n-        return 0\\n-    return sum(nums) / (len(nums) - 1)\\n+    return sum(nums) / len(nums)";\nconst D2="--- a/calc.py\\n+++ b/calc.py\\n def average(nums):\\n     if not nums:\\n         return 0\\n-    return sum(nums) / (len(nums) - 1)\\n+    return sum(nums) / len(nums)";\nconst M={p:"nvidia/Nemotron-3-Ultra-550b-a55b",c:"nvidia/nemotron-3-super-120b-a12b",t:"nvidia/NVIDIA-Nemotron-3-Nano-30B-A3B"};\nconst DEMO=[\n[500,{step:"load",status:"done",detail:"Loaded 2 files"}],\n[300,{step:"planner",status:"running",model:M.p}],\n[2400,{step:"planner",status:"done",model:M.p,total:1840,detail:"average() divides by len(nums) - 1 instead of len(nums), so every result is too high.",steps:["Change the divisor to len(nums)","Keep the empty-list guard","Add a regression test"]}],\n[400,{step:"coder",status:"running",model:M.c,attempt:1}],\n[2000,{step:"coder",status:"done",model:M.c,attempt:1,total:2960,diff:D1}],\n[400,{step:"tester",status:"running",model:M.t,attempt:1}],\n[1700,{step:"tester",status:"failed",model:M.t,attempt:1,total:3220,output:"FAILED test_calc.py::test_empty - ZeroDivisionError: division by zero\\n1 failed, 1 passed in 0.03s"}],\n[500,{step:"coder",status:"running",model:M.c,attempt:2}],\n[1800,{step:"coder",status:"done",model:M.c,attempt:2,total:4150,diff:D2}],\n[400,{step:"tester",status:"running",model:M.t,attempt:2}],\n[1500,{step:"tester",status:"done",model:M.t,attempt:2,total:4310,output:"3 passed in 0.02s"}],\n[600,{step:"final",status:"done",total:4310,summary:"### Fix average() divisor\\n\\n- Divide by len(nums), not len(nums) - 1\\n- Keep the empty-list guard (the first attempt removed it and broke test_empty)\\n- Add a regression test\\n\\nVerified: 3 tests pass."}]];\nasync function typeText(el,t){el.value="";for(const ch of t){el.value+=ch;await new Promise(r=>setTimeout(r,RM?0:22))}}\nconst wait=ms=>new Promise(r=>setTimeout(r,ms));\nasync function demo(){reset();$("mode").textContent="Demo mode";$("go").disabled=$("demo").disabled=true;\n $("lab").scrollIntoView();await wait(900);$("repo").value="example:py_bug";\n await typeText($("bug"),"average([2, 4, 6]) returns 6.0 instead of 4.0, and test_calc.py fails.");await wait(400);\n const b=$("go"),r=b.getBoundingClientRect();b.dispatchEvent(new PointerEvent("pointerdown",{bubbles:true,clientX:r.left+r.width/2,clientY:r.top+r.height/2}));await wait(500);\n $("out").scrollIntoView();await wait(900);for(const[d,m]of DEMO){await wait(d);handle(m)}}\n\n$("demo").onclick=demo;$("own").onclick=()=>{$("lab").scrollIntoView();$("bug").focus()};$("go").onclick=live;\naddEventListener("keydown",e=>{if(e.key==="d"&&!e.target.closest("input,textarea")&&!$("demo").disabled)demo()});\n</script></body></html>\n'
